def _warn(message: str) -> None:
    """Report a degraded parse on stderr without failing the read."""
    print(f"tracker(teamwork): {message}", file=sys.stderr)


# ── Teamwork Mappings ───────────────────────────────────────────────────

# Synaptory priority -> Teamwork native priority
PRIORITY_MAP = {
    "Must":   "high",
    "Should": "high",
    "Could":  "medium",
    "Won't":  "low",
}
PRIORITY_REVERSE = {
    "high":   "Must",
    "medium": "Could",
    "low":    "Won't",
    "none":   "",
    "":       "",
}

SIZE_TO_POINTS = {"S": 1, "M": 3, "L": 5, "XL": 8}
POINTS_TO_SIZE = {v: k for k, v in SIZE_TO_POINTS.items()}

# Synaptory status -> Teamwork workflow stage config key
# The actual stage IDs come from .synaptory.yaml workflow_stages; this maps
# the synaptory status name to the config key used to look up the stage ID.
STATUS_STAGE_MAP = {
    "BACKLOG":              "BACKLOG",              # fallback: TO_DO
    "TO_DO":                "TO_DO",
    "IN_PROGRESS":          "IN_PROGRESS",
    "IN_REVIEW":            "IN_REVIEW",            # fallback: IN_PROGRESS
    # #116: projects with per_story_acceptance enabled can configure an
    # AWAITING_ACCEPTANCE stage; trackers without one fall back to
    # IN_REVIEW + the `awaiting-acceptance` tag below.
    "AWAITING_ACCEPTANCE":  "AWAITING_ACCEPTANCE",  # fallback: IN_REVIEW
    "DONE":                 "DONE",
    "COMPLETED":            "DONE",
    # PO cancelled — same column as DONE on the board with a `cancelled`
    # tag so the audit trail records that it wasn't accepted.
    "CANCELLED":            "DONE",
}

# Tag-based status indicators — Teamwork uses tags for statuses that can't be
# fully expressed by workflow stages alone (same pattern as "blocked" tag).
STATUS_TAGS = {
    "BLOCKED":              "blocked",
    "IN_REVIEW":            "in-review",
    "AWAITING_ACCEPTANCE":  "awaiting-acceptance",  # #116
    "CANCELLED":            "cancelled",            # #116
}

# Tag names for entity type identification
ENTITY_TAGS = {
    "epic":  "hc:epic",
    "story": "hc:story",
    "task":  "hc:task",
    "bug":   "hc:bug",
}


_ENTITY_TYPE_PREFIXES = {
    "B-": "bug", "BUG-": "bug",
    "EPIC-": "epic",
    "T-": "task", "TASK-": "task",
}


def _detect_entity_type(entity_id: str) -> str:
    """Detect entity type from ID prefix. Returns 'story' as default."""
    upper = entity_id.upper()
    for prefix, etype in _ENTITY_TYPE_PREFIXES.items():
        if upper.startswith(prefix):
            return etype
    return "story"


def _clean_title(raw_title: str) -> str:
    """Strip the synaptory ID prefix from a title."""
    m = re.match(r'^[A-Z]+-\w+\s*[—–\-:]\s*', raw_title)
    if m:
        return raw_title[m.end():].strip()
    return raw_title


_DEFAULT_STORY_SECTIONS = [
    "Story", "Objective", "User Impact Statement",
    "Acceptance Criteria", "Business Rules", "Testing Notes",
    "Technical Context", "Data Model", "NFRs", "Feature List",
    "Dependencies", "UI Reference",
]


def _load_template_sections(template_path: str) -> list[str]:
    """Extract ## heading names from a tracker template file.

    Returns the ordered list of section headings found in the template.
    Falls back to _DEFAULT_STORY_SECTIONS if the file doesn't exist
    or contains no headings.
    """
    p = Path(template_path) if template_path else None
    if not p or not p.exists():
        return []
    try:
        text = p.read_text(encoding="utf-8")
    except OSError:
        return []
    sections = []
    for line in text.splitlines():
        m = re.match(r'^##\s+(.+)', line.strip())
        if m:
            heading = m.group(1).strip()
            # Strip template placeholders like {{...}}
            heading = re.sub(r'\{\{.*?\}\}', '', heading).strip()
            if heading:
                sections.append(heading)
    return sections or []


def _build_description(entity_id: str, feature: str = "",
                       raw_text: str = "",
                       acceptance_criteria: Optional[list[AcceptanceCriterion]] = None,
                       template_path: str = "") -> str:
    """Build a rich description from story/epic Markdown source.

    AC format uses ``* [x]`` / ``* [ ]`` markdown checkboxes which Teamwork
    renders as interactive checklists without strikethrough on the AC title.

    If template_path is provided, section ordering is derived from the
    template's ``## Heading`` lines. Otherwise, uses _DEFAULT_STORY_SECTIONS.
    """
    parts = [f"> synaptory: `{entity_id}`"]
    if feature:
        parts[0] += f" | Feature: `{feature}`"

    if raw_text:
        sections = _load_template_sections(template_path) or _DEFAULT_STORY_SECTIONS
        for section_name in sections:
            section = _extract_md_section(raw_text, section_name)
            if section:
                if section_name == "Acceptance Criteria":
                    # Convert ACs to checklist format (* [x] / * [ ])
                    parts.append("\n## Acceptance Criteria\n")
                    current_ac = None
                    for line in section.splitlines():
                        stripped = line.strip()
                        ac_match = re.match(
                            r'\*\*AC-(\w+)\s*[—–\-]*\s*([^*]*)\*\*:?\s*(.*)', stripped,
                        )
                        if ac_match:
                            ac_id = ac_match.group(1)
                            ac_title = ac_match.group(2).strip().rstrip(":").strip()
                            after = ac_match.group(3).strip()
                            label = ac_title or after or f"AC-{ac_id}"
                            parts.append(f"* [ ] **AC-{ac_id}: {label}**")
                            current_ac = ac_id
                        elif stripped.startswith("- Given") or stripped.startswith("- When") or stripped.startswith("- Then"):
                            parts.append(f"  {stripped}")
                        elif current_ac and stripped.startswith("-"):
                            parts.append(f"  {stripped}")
                else:
                    parts.append(f"\n## {section_name}\n\n{section}")
    elif acceptance_criteria:
        parts.append("\n## Acceptance Criteria\n")
        for ac in acceptance_criteria:
            marker = "[x]" if ac.met else "[ ]"
            parts.append(f"* {marker} **{ac.id}: {ac.text}**")
            # Append Given/When/Then if provided
            if getattr(ac, "given", ""):
                parts.append(f"\n  * Given {ac.given}\n")
            if getattr(ac, "when", ""):
                parts.append(f"  * When {ac.when}\n")
            if getattr(ac, "then", ""):
                parts.append(f"  * Then {ac.then}")

    return "\n".join(parts)


def _extract_md_section(text: str, heading: str) -> str:
    """Extract content under a markdown heading until next same-level heading."""
    lines = text.splitlines()
    in_section = False
    section_lines = []
    heading_level = 0
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("#"):
            hashes = len(stripped) - len(stripped.lstrip("#"))
            title = stripped.lstrip("#").strip()
            if title.lower() == heading.lower():
                in_section = True
                heading_level = hashes
                continue
            elif in_section and hashes <= heading_level:
                break
        if in_section:
            section_lines.append(line)
    return "\n".join(section_lines).strip()


class TeamworkAdapter(ArtifactAdapter):
    """Adapter using Teamwork Projects for ticket tracking."""

    def __init__(self, project_dir: Path, config, spec=None):
        """Construct the adapter.

        spec — optional SpecConfig binding the adapter to one spec in a
        multi-spec Teamwork-backed project (docs/multi-spec-design.md).
        When set, every read filters by the spec's tag (or restricts to
        a single tasklist), every write applies the corresponding tag /
        tasklist side-effect, and cache files route to
        `.synaptory/.orchestrator/specs/{spec.id}/`. Legacy single-spec
        behavior is unchanged when spec is None.
        """
        super().__init__(project_dir, config)
        self.spec = spec

        # Per-spec site_name / project_id override (rare — multi-spec stays
        # within one Teamwork project).
        site = (spec.teamwork.site_name if (spec is not None and spec.teamwork and spec.teamwork.site_name)
                else config.teamwork.site_name)
        project_id = (spec.teamwork.project_id if (spec is not None and spec.teamwork and spec.teamwork.project_id)
                      else config.teamwork.project_id)
        self.transport = TeamworkTransport(site_name=site, project_id=project_id)
        if spec is not None and spec.teamwork and spec.teamwork.sprint_milestone_prefix:
            self.milestone_prefix = spec.teamwork.sprint_milestone_prefix
        else:
            self.milestone_prefix = config.teamwork.sprint_milestone_prefix

        # Per-spec workflow_stages take precedence — Teamwork stage IDs are
        # per-project, so specs targeting different projects must each carry
        # their own map. Empty per-spec falls back to the top-level config.
        spec_workflow_stages: dict[str, int] = {}
        if spec is not None and spec.teamwork and spec.teamwork.workflow_stages:
            spec_workflow_stages = spec.teamwork.workflow_stages
        self._config_workflow_stages: dict[str, int] = (
            spec_workflow_stages or getattr(config.teamwork, 'workflow_stages', {})
        )
        # Per-spec issue_type / status_map overrides fall back to the
        # top-level maps when empty (same pattern as workflow_stages).
        # issue_type remaps the entity *tag* names (defaults: ENTITY_TAGS);
        # status_map remaps the status *tag* names (defaults: STATUS_TAGS).
        # Empty ⇒ unchanged behavior.
        spec_types = (dict(getattr(spec.teamwork, "issue_type_overrides", {}) or {})
                      if (spec is not None and spec.teamwork) else {})
        self._issue_type_overrides = spec_types or dict(
            getattr(config.teamwork, "issue_type_overrides", {}) or {})
        spec_status = (dict(getattr(spec.teamwork, "status_map", {}) or {})
                       if (spec is not None and spec.teamwork) else {})
        self._status_map_override = spec_status or dict(
            getattr(config.teamwork, "status_map", {}) or {})
        self._sprint_tasklist_map: dict[int, int] = {}  # sprint_num -> tasklist_id
        self._backlog_tasklist_id: Optional[int] = None  # lazy fallback for unsprinted tasks
        self._id_map: Optional[dict] = None
        self._tag_cache: dict[str, int] = {}  # name -> tag_id
        # Cached lookup for the spec's discriminator tag id (resolved lazily
        # on first read/write so adapters constructed without auth still
        # instantiate cleanly).
        self._spec_tag_id: Optional[int] = None

        if spec is not None:
            spec_dir = project_dir / ".synaptory" / ".orchestrator" / "specs" / spec.id
            self._id_map_path = spec_dir / "tracker-id-map.json"
            self._backlog_order_path = spec_dir / "backlog-order.json"
            self._local_cache_path = spec_dir / "tracker-data.json"
        else:
            self._id_map_path = project_dir / ".synaptory" / ".orchestrator" / "tracker-id-map.json"
            self._backlog_order_path = project_dir / ".synaptory" / ".orchestrator" / "backlog-order.json"
            self._local_cache_path = project_dir / ".synaptory" / ".orchestrator" / "tracker-data.json"

    # ── Override resolution ──────────────────────────────────

    def _entity_tag(self, entity_type: str, default_key: str = "story") -> str:
        """Resolve the entity *tag* name for a synaptory entity kind.

        Per-entity override (from the `issue_type` config) wins; otherwise
        the built-in ENTITY_TAGS default, falling back to ENTITY_TAGS[default_key]
        for unknown kinds.
        """
        overrides = getattr(self, "_issue_type_overrides", None) or {}
        return (overrides.get(entity_type)
                or ENTITY_TAGS.get(entity_type, ENTITY_TAGS[default_key]))

    def _status_tag(self, canonical: str) -> str:
        """Resolve the status *tag* name for a tag-backed canonical state
        (BLOCKED, IN_REVIEW, AWAITING_ACCEPTANCE, CANCELLED). Per-project
        `status_map` override wins; otherwise the STATUS_TAGS default.
        """
        override = getattr(self, "_status_map_override", None) or {}
        return (override.get(canonical)
                or STATUS_TAGS.get(canonical, ""))

    # ── Spec filter helpers ──────────────────────────────────

    def _ensure_spec_writeable(self, op: str) -> None:
        """Teamwork specs are always writeable — no read-only filter types."""
        pass  # all current Teamwork filter types support writes

    def _resolve_spec_tag_id(self) -> Optional[int]:
        """Lazily resolve the spec's tag name to a Teamwork tag id.

        Returns None if the spec is not tag-bound or the lookup fails (in
        which case we fall back to client-side filtering by tag name).
        """
        if self.spec is None or self.spec.filter.type != "tag":
            return None
        if self._spec_tag_id is not None:
            return self._spec_tag_id
        try:
            tag_id = self.transport.get_or_create_tag(self.spec.filter.value)
            self._spec_tag_id = tag_id
            return tag_id
        except Exception:
            return None

    def _spec_tag_filter_ids(self) -> Optional[list[int]]:
        """Return [tag_id] for a tag-bound spec — to be added to the
        `tag_ids` kwarg of transport.list_tasks(). None for non-tag specs."""
        if self.spec is None or self.spec.filter.type != "tag":
            return None
        tag_id = self._resolve_spec_tag_id()
        return [tag_id] if tag_id else None

    def _spec_tasklist_id(self) -> Optional[int]:
        """Return the tasklist id for a tasklist-bound spec, parsing the
        config's filter.value as int. None for non-tasklist specs."""
        if self.spec is None or self.spec.filter.type != "tasklist":
            return None
        try:
            return int(self.spec.filter.value)
        except (TypeError, ValueError):
            return None

    def _apply_spec_write_side_effect(
        self, *, tag_ids: list, tasklist_id: Optional[int] = None,
    ) -> tuple[list, Optional[int]]:
        """Apply the spec write side-effect to task-creation kwargs.

        - tag      → append the spec's tag id to `tag_ids` (deduped).
        - tasklist → set `tasklist_id` to the spec's tasklist if not already set.
        """
        if self.spec is None:
            return tag_ids, tasklist_id
        if self.spec.filter.type == "tag":
            tid = self._resolve_spec_tag_id()
            if tid and tid not in tag_ids:
                tag_ids.append(tid)
        elif self.spec.filter.type == "tasklist":
            if not tasklist_id:
                tlid = self._spec_tasklist_id()
                if tlid:
                    tasklist_id = tlid
        return tag_ids, tasklist_id

    # ── Lifecycle ─────────────────────────────────────────────

    def initialize(self) -> None:
        """Verify auth and pre-create tags. Tasklists are created per-sprint in create_sprint()."""
        if not self.transport.check_api():
            raise AdapterAuthError(
                "Teamwork API not configured. Required:\n"
                "  TEAMWORK_API_KEY — API key from Teamwork → Edit My Details → API tab\n"
                "  .synaptory.yaml tracker.teamwork.site_name — your Teamwork subdomain\n"
                "  .synaptory.yaml tracker.teamwork.project_id — numeric project ID\n\n"
                "Tip: use direnv for project-scoped keys:\n"
                "  echo 'export TEAMWORK_API_KEY=\"your-key\"' > .envrc && direnv allow .\n"
                "  Add .envrc to .gitignore."
            )

        # Pre-create entity type tags and status tags (override-resolved), cache IDs
        entity_tags = [self._entity_tag(e) for e in ENTITY_TAGS]
        status_tags = [self._status_tag(s) for s in STATUS_TAGS]
        for tag_name in entity_tags + status_tags:
            self._tag_cache[tag_name] = self.transport.get_or_create_tag(tag_name)

        # Pre-create points tags
        for pts in [1, 2, 3, 5, 8, 13]:
            name = f"points:{pts}"
            self._tag_cache[name] = self.transport.get_or_create_tag(name)

        self._load_id_map()

    def health_check(self) -> dict:
        h = self.transport.health_check()
        h["backend"] = "teamwork"
        h["sprint_tasklist_map"] = self._sprint_tasklist_map
        h["id_map_loaded"] = self._id_map is not None
        return h

    # ── Local Cache Write-Through ────────────────────────────

    def _update_local_cache_status(self, story_id: str, status: str) -> None:
        """Write-through: keep tracker-data.json in sync after Teamwork updates."""
        if not self._local_cache_path.exists():
            return
        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
            for s in data.get("stories", []):
                if s["id"] == story_id:
                    s["status"] = status
                    break
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except (json.JSONDecodeError, OSError):
            pass  # cache is best-effort; don't fail the primary operation

    def sync_to_local_cache(self, sprint_num: Optional[int] = None) -> dict:
        """Pull current status from Teamwork and update tracker-data.json.

        Args:
            sprint_num: If given, sync only stories in that sprint.
                        If None, sync all stories.

        Returns:
            dict with sync stats: {"synced": N, "errors": [...]}
        """
        stats: dict = {"synced": 0, "added": 0, "errors": []}
        if not self._local_cache_path.exists():
            # Bootstrap an empty cache so the first sync in a fresh workspace
            # works (#108). `migrate` is the wrong direction for new projects —
            # there's nothing local to push; the user wants to pull remote.
            self._local_cache_path.parent.mkdir(parents=True, exist_ok=True)
            self._local_cache_path.write_text(
                json.dumps({"epics": [], "sprints": [], "stories": []}, indent=2),
                encoding="utf-8",
            )

        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError) as e:
            stats["errors"].append(f"Failed to read local cache: {e}")
            return stats

        # Build lookup of local stories by ID
        local_stories = {s["id"]: s for s in data.get("stories", [])}

        # Fetch live stories from Teamwork
        if sprint_num is not None:
            live_stories = self.get_sprint_backlog(sprint_num)
        else:
            live_stories = self.list_stories()

        for story in live_stories:
            if story.id in local_stories:
                local_stories[story.id]["status"] = story.status
                stats["synced"] += 1
            else:
                # Story exists in Teamwork but not in local cache — add it
                data["stories"].append({
                    "id": story.id, "title": story.title,
                    "feature": story.feature, "epic": story.epic,
                    "priority": story.priority, "status": story.status,
                    "size": story.size, "sprint": story.sprint,
                    "ac_count": story.ac_count, "acceptance_criteria": [],
                    "raw_text": "",
                })
                stats["added"] += 1

        try:
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except OSError as e:
            stats["errors"].append(f"Failed to write local cache: {e}")

        return stats

    # ── Epic Operations ──────────────────────────────────────

    def list_epics(self) -> list[Epic]:
        id_map = self._load_id_map()
        return [
            Epic(
                id=synaptory_id,
                title=entry.get("title", synaptory_id),
                tracker_id=str(entry.get("teamwork_id", "")),
                tracker_url=entry.get("teamwork_url", ""),
            )
            for synaptory_id, entry in id_map.items()
            if entry.get("type") == "epic"
        ]

    def get_epic(self, epic_id: str) -> Optional[Epic]:
        id_map = self._load_id_map()
        entry = id_map.get(epic_id)
        if entry and entry.get("type") == "epic":
            return Epic(
                id=epic_id,
                title=entry.get("title", epic_id),
                tracker_id=str(entry.get("teamwork_id", "")),
                tracker_url=entry.get("teamwork_url", ""),
            )
        return None

    def create_epic(self, epic: Epic, raw_text: str = "") -> Epic:
        # Epics are represented as Teamwork tags (not tasks) so they can be
        # applied to stories across multiple sprint tasklists.
        id_tag_id = self.transport.get_or_create_tag(epic.id)
        self._tag_cache[epic.id] = id_tag_id

        epic.tracker_id = str(id_tag_id)
        epic.tracker_url = ""
        self._save_id_mapping(epic.id, id_tag_id, type="epic", title=_clean_title(epic.title))
        return epic

    def update_epic(self, epic_id: str, **fields) -> Epic:
        id_map = self._load_id_map()
        entry = id_map.get(epic_id)
        if entry is None or entry.get("type") != "epic":
            raise AdapterError(f"Epic not found in ID map: {epic_id}")
        if "title" in fields:
            entry["title"] = _clean_title(fields["title"])
            self._id_map_path.write_text(json.dumps(id_map, indent=2), encoding="utf-8")
        return self.get_epic(epic_id) or Epic(id=epic_id, title=fields.get("title", ""))

    # ── Story Operations ─────────────────────────────────────

    def list_stories(self, epic_id: Optional[str] = None,
                     sprint: Optional[int] = None) -> list[Story]:
        story_tag_id = self._get_tag_id(self._entity_tag("story"))
        milestone_id = None
        if sprint is not None:
            milestone_id = self._get_milestone_id(sprint)

        tag_ids = [story_tag_id]
        spec_tags = self._spec_tag_filter_ids()
        if spec_tags:
            tag_ids = list(set(tag_ids + spec_tags))

        kwargs: dict = {"tag_ids": tag_ids, "milestone_id": milestone_id}
        tl = self._spec_tasklist_id()
        if tl:
            kwargs["tasklist_id"] = tl

        tasks = self.transport.list_tasks(**kwargs)

        stories = [self._task_to_story(t) for t in tasks]

        if epic_id:
            stories = [s for s in stories if s.epic == epic_id]

        return stories

    def get_story(self, story_id: str) -> Optional[Story]:
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            return None
        try:
            task = self.transport.get_task(tw_id)
            return self._task_to_story(task)
        except AdapterError:
            return None

    def create_ticket(self, story: Story, raw_text: str = "") -> Story:
        self._ensure_spec_writeable("create_ticket")
        # Detect entity type from ID prefix (B- → bug, T- → task, etc.)
        entity_type = _detect_entity_type(story.id)

        # Collect tag IDs — use correct entity tag for the type
        id_tag = self.transport.get_or_create_tag(story.id)
        type_tag = self._get_tag_id(self._entity_tag(entity_type))
        tag_ids = [id_tag, type_tag]

        # Priority
        priority = PRIORITY_MAP.get(story.priority)

        # Points tag
        if story.size in SIZE_TO_POINTS:
            pts_tag = self._get_tag_id(f"points:{SIZE_TO_POINTS[story.size]}")
            tag_ids.append(pts_tag)

        # Blocked tag
        if story.status == "BLOCKED":
            blocked_tag = self._get_tag_id(self._status_tag("BLOCKED"))
            tag_ids.append(blocked_tag)

        # Epic as a tag (not a parent task)
        if story.epic:
            epic_tag_id = self._get_tag_id(story.epic)
            tag_ids.append(epic_tag_id)

        # Resolve sprint tasklist and milestone
        tasklist_id = self._get_or_create_backlog_tasklist()
        milestone_id = None
        if story.sprint:
            try:
                sprint_num = int(story.sprint)
                tl = self._get_sprint_tasklist_id(sprint_num)
                if tl is not None:
                    tasklist_id = tl
                milestone_id = self._get_milestone_id(sprint_num)
            except (ValueError, TypeError):
                pass

        # Build description — resolve template path from config by entity type
        tmpl_path = ""
        templates_cfg = getattr(self.config, 'templates', None)
        if templates_cfg:
            # Try entity-specific template first, then fall back to story template
            tmpl_path = getattr(templates_cfg, entity_type, '') or ''
            if not tmpl_path and entity_type != "story":
                tmpl_path = getattr(templates_cfg, 'story', '') or ''
            if tmpl_path:
                tmpl_path = str(self.project_dir / tmpl_path)
        description = _build_description(
            story.id, story.feature,
            raw_text or story.raw_text,
            story.acceptance_criteria,
            template_path=tmpl_path,
        )
        title = _clean_title(story.title)

        # Spec write side-effect: append spec tag (tag-bound) or override
        # tasklist (tasklist-bound). For tasklist-bound specs we keep the
        # sprint-tasklist if the story has a sprint — that's a stronger
        # caller intent than the spec default.
        if self.spec is not None:
            if self.spec.filter.type == "tag":
                tag_ids, _ = self._apply_spec_write_side_effect(tag_ids=tag_ids)
            elif self.spec.filter.type == "tasklist" and not story.sprint:
                tag_ids, tasklist_id = self._apply_spec_write_side_effect(
                    tag_ids=tag_ids, tasklist_id=tasklist_id,
                )

        task = self.transport.create_task(
            task_list_id=tasklist_id,
            name=title,
            description=description,
            tag_ids=tag_ids,
            priority=priority,
            milestone_id=milestone_id,
        )
        tw_id = task.get("id", 0)
        url = self._build_task_url(tw_id)
        story.tracker_id = str(tw_id)
        story.tracker_url = url
        self._save_id_mapping(story.id, tw_id, url)
        # Set initial workflow stage to BACKLOG (or TO_DO fallback)
        initial_stage = self._config_workflow_stages.get("BACKLOG") or self._config_workflow_stages.get("TO_DO")
        if initial_stage and tw_id:
            self.transport.move_workflow_stage(tw_id, initial_stage)
        return story

    def update_story_status(self, story_id: str, status: str, *,
                            allow_skip: bool = False) -> Story:
        """Update story status — moves workflow stage AND manages tags/completion.

        5-stage workflow:
        - BACKLOG:     Stage -> BACKLOG (or TO_DO fallback), task open
        - TO_DO:       Stage -> TO_DO,          task open
        - IN_PROGRESS: Stage -> IN_PROGRESS,    task open
        - IN_REVIEW:           Stage -> IN_REVIEW (or IN_PROGRESS fallback), task open, +in-review tag
        - AWAITING_ACCEPTANCE: Stage -> AWAITING_ACCEPTANCE (or IN_REVIEW fallback), task open, +awaiting-acceptance tag  (#116)
        - DONE:                Stage -> DONE,           task marked completed (HITL approved)
        - COMPLETED:           Alias for DONE
        - CANCELLED:           Stage -> DONE, +cancelled tag, task marked completed  (#116)
        - BLOCKED:             No stage change,         task open, +blocked tag
        """
        self._validate_status_transition(story_id, status, allow_skip)
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            raise AdapterError(f"Story not found in ID map: {story_id}")

        status = status.upper()
        wf_stages = getattr(self, '_config_workflow_stages', None) or {}
        # Status tag names resolve through the per-project status_map override
        # (empty ⇒ the STATUS_TAGS defaults, unchanged behavior).
        blocked_tag_id = self._get_tag_id(self._status_tag("BLOCKED"))
        in_review_tag_id = self._get_tag_id(self._status_tag("IN_REVIEW"))
        awaiting_tag_id = self._get_tag_id(self._status_tag("AWAITING_ACCEPTANCE"))
        cancelled_tag_id = self._get_tag_id(self._status_tag("CANCELLED"))

        # Resolve workflow stage from STATUS_STAGE_MAP with fallbacks
        stage_key = STATUS_STAGE_MAP.get(status)
        target_stage = wf_stages.get(stage_key) if stage_key else None
        # Fallbacks for unconfigured stages
        if not target_stage and status == "BACKLOG":
            target_stage = wf_stages.get("TO_DO")
        if not target_stage and status == "IN_REVIEW":
            target_stage = wf_stages.get("IN_PROGRESS")
        if not target_stage and status == "AWAITING_ACCEPTANCE":
            # Trackers without an Awaiting Acceptance column collapse onto
            # IN_REVIEW (then IN_PROGRESS) — the `awaiting-acceptance` tag
            # still records the lifecycle stage in the audit trail.
            target_stage = wf_stages.get("IN_REVIEW") or wf_stages.get("IN_PROGRESS")

        if status == "CANCELLED":
            # PO cancelled — same column as DONE on the board with a
            # `cancelled` tag so velocity / DoD aggregation can exclude it.
            if target_stage:
                self.transport.move_workflow_stage(tw_id, target_stage)
            try:
                self.transport.complete_task(tw_id)
            except AdapterError:
                pass
            self._add_tag_to_task(tw_id, cancelled_tag_id)
            self._remove_tag_from_task(tw_id, blocked_tag_id)
            self._remove_tag_from_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, awaiting_tag_id)
        elif status in ("DONE", "COMPLETED"):
            # HITL approved — move stage AND complete task
            if target_stage:
                self.transport.move_workflow_stage(tw_id, target_stage)
            try:
                self.transport.complete_task(tw_id)
            except AdapterError:
                # Already complete is a no-op, not an error (#115 idempotency:
                # the pipeline may re-fire `update_story_status("DONE")` if a
                # transition is replayed or the sprint is reclosed).
                pass
            self._remove_tag_from_task(tw_id, blocked_tag_id)
            self._remove_tag_from_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, awaiting_tag_id)
        elif status == "BLOCKED":
            # No stage change, add blocked tag, ensure task is open
            try:
                self.transport.uncomplete_task(tw_id)
            except AdapterError:
                pass
            self._add_tag_to_task(tw_id, blocked_tag_id)
            self._remove_tag_from_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, awaiting_tag_id)
        elif status == "AWAITING_ACCEPTANCE":
            # Move stage (or fall back to IN_REVIEW column), add the
            # awaiting-acceptance tag for reliable round-trip.
            if target_stage:
                self.transport.move_workflow_stage(tw_id, target_stage)
            try:
                self.transport.uncomplete_task(tw_id)
            except AdapterError:
                pass
            self._add_tag_to_task(tw_id, awaiting_tag_id)
            self._remove_tag_from_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, blocked_tag_id)
        elif status == "IN_REVIEW":
            # Move stage + add in-review tag for reliable round-trip
            if target_stage:
                self.transport.move_workflow_stage(tw_id, target_stage)
            try:
                self.transport.uncomplete_task(tw_id)
            except AdapterError:
                pass
            self._add_tag_to_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, blocked_tag_id)
            self._remove_tag_from_task(tw_id, awaiting_tag_id)
        else:
            # BACKLOG, TO_DO, IN_PROGRESS — move stage, ensure open, clear status tags
            if target_stage:
                self.transport.move_workflow_stage(tw_id, target_stage)
            try:
                self.transport.uncomplete_task(tw_id)
            except AdapterError:
                pass
            self._remove_tag_from_task(tw_id, blocked_tag_id)
            self._remove_tag_from_task(tw_id, in_review_tag_id)
            self._remove_tag_from_task(tw_id, awaiting_tag_id)

        # Write-through to local cache
        self._update_local_cache_status(story_id, status)

        story = self.get_story(story_id)
        if story:
            return story
        return Story(id=story_id, title=story_id, status=status)

    def update_story(self, story_id: str, **fields) -> Story:
        if "status" in fields:
            return self.update_story_status(story_id, fields["status"])
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            raise AdapterError(f"Story not found: {story_id}")
        updates = {}
        if "title" in fields:
            updates["name"] = _clean_title(fields["title"])
        if "priority" in fields and fields["priority"] in PRIORITY_MAP:
            updates["priority"] = PRIORITY_MAP[fields["priority"]]
        if updates:
            self.transport.update_task(tw_id, **updates)
        # Handle size (points tag swap)
        if "size" in fields and fields["size"] in SIZE_TO_POINTS:
            self._update_points_tag(tw_id, fields["size"])
        return self.get_story(story_id) or Story(id=story_id, title="")

    def get_acceptance_criteria(self, story_id: str) -> list[AcceptanceCriterion]:
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            return []
        task = self.transport.get_task(tw_id)
        description = task.get("description", "")
        return self._parse_checklist_acs(description)

    def update_acceptance_criteria(self, story_id: str, ac_id: str,
                                   met: bool) -> AcceptanceCriterion:
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            raise AdapterError(f"Story not found: {story_id}")
        task = self.transport.get_task(tw_id)
        description = task.get("description", "")
        # Normalize all AC checkbox formats to * [x] / * [ ]
        # Supports: * [x], - [x], * ✅, - ✅, * ⬜, - ⬜
        new_marker = "[x]" if met else "[ ]"
        replacement = f"* {new_marker} **{ac_id}:"
        # Match any existing format for this AC
        check_pattern_star = rf"\* \[[ xX]\] \*\*{re.escape(ac_id)}:"
        check_pattern_dash = rf"- \[[ xX]\] \*\*{re.escape(ac_id)}:"
        emoji_pattern_star = rf"\* [✅⬜] \*\*{re.escape(ac_id)}:"
        emoji_pattern_dash = rf"- [✅⬜] \*\*{re.escape(ac_id)}:"
        new_description = description
        for pattern in [check_pattern_star, check_pattern_dash,
                        emoji_pattern_star, emoji_pattern_dash]:
            new_description = re.sub(pattern, replacement, new_description)
        if new_description != description:
            self.transport.update_task(tw_id, description=new_description)
        return AcceptanceCriterion(id=ac_id, text="", met=met)

    # ── Task & Bug Operations ────────────────────────────────

    def create_aux_ticket(self, ticket_type: str, title: str,
                          parent_id: Optional[str] = None, **fields) -> dict:
        self._ensure_spec_writeable("create_aux_ticket")
        tag_name = self._entity_tag(ticket_type, default_key="task")
        type_tag = self._get_tag_id(tag_name)
        tag_ids = [type_tag]

        parent_task_id = None
        if parent_id:
            parent_task_id = self._resolve_id(parent_id)

        tasklist_id = self._get_or_create_backlog_tasklist()
        if self.spec is not None:
            tag_ids, tasklist_id = self._apply_spec_write_side_effect(
                tag_ids=tag_ids, tasklist_id=tasklist_id,
            )

        task = self.transport.create_task(
            task_list_id=tasklist_id,
            name=title,
            description=fields.get("body", ""),
            parent_task_id=parent_task_id,
            tag_ids=tag_ids,
        )
        tw_id = task.get("id", 0)
        return {
            "id": str(tw_id), "title": title, "type": ticket_type,
            "url": self._build_task_url(tw_id),
        }

    def close_ticket(self, ticket_id: str, resolution: str = "") -> dict:
        tw_id = self._resolve_id(ticket_id)
        if tw_id is None:
            try:
                tw_id = int(ticket_id)
            except ValueError:
                raise AdapterError(f"Ticket not found: {ticket_id}")
        self.transport.complete_task(tw_id)
        return {"id": ticket_id, "status": "DONE", "resolution": resolution}

    # ── Sprint Operations ────────────────────────────────────

    def list_sprints(self) -> list[SprintInfo]:
        milestones = self.transport.list_milestones()
        result = []
        for ms in milestones:
            name = ms.get("name", "")
            if not name.startswith(self.milestone_prefix):
                continue
            num_str = name[len(self.milestone_prefix):]
            try:
                num = int(num_str)
            except ValueError:
                continue

            # Get tasks assigned to this milestone
            story_tag_id = self._get_tag_id(self._entity_tag("story"))
            tag_ids = [story_tag_id]
            spec_tags = self._spec_tag_filter_ids()
            if spec_tags:
                tag_ids = list(set(tag_ids + spec_tags))
            list_kwargs: dict = {"milestone_id": ms.get("id"), "tag_ids": tag_ids}
            tl = self._spec_tasklist_id()
            if tl:
                list_kwargs["tasklist_id"] = tl
            tasks = self.transport.list_tasks(**list_kwargs)
            story_ids = self._extract_synaptory_ids(tasks)

            dates = ""
            deadline = ms.get("deadline", "")
            if deadline:
                dates = f"to {deadline}"

            result.append(SprintInfo(
                number=num,
                goal=ms.get("description", name),
                dates=dates,
                story_ids=story_ids,
                story_count=len(story_ids),
                tracker_id=str(ms.get("id", "")),
                tracker_url=self._build_milestone_url(ms.get("id", 0)),
            ))
        return sorted(result, key=lambda s: s.number)

    def get_sprint(self, sprint_num: int) -> Optional[SprintInfo]:
        for s in self.list_sprints():
            if s.number == sprint_num:
                return s
        return None

    def create_sprint(self, sprint: SprintInfo) -> SprintInfo:
        name = f"{self.milestone_prefix}{sprint.number}"

        # Parse end date from dates field (e.g. "2026-04-01 to 2026-04-14")
        deadline = None
        if sprint.dates:
            parts = sprint.dates.split(" to ")
            if len(parts) == 2:
                deadline = parts[1].strip()
            elif len(parts) == 1:
                deadline = parts[0].strip()

        ms = self.transport.create_milestone(
            name=name,
            description=sprint.goal,
            deadline=deadline,
        )
        ms_id = ms.get("id", 0)
        sprint.tracker_id = str(ms_id)
        sprint.tracker_url = self._build_milestone_url(ms_id)

        # Create a tasklist for this sprint (linked to the milestone) so
        # Board/List/Table views are meaningful — matches migration script behavior
        tl_name = f"Sprint {sprint.number} — {sprint.goal}" if sprint.goal else f"Sprint {sprint.number}"
        tl_id = self.transport.get_or_create_tasklist(tl_name, milestone_id=ms_id)
        self._sprint_tasklist_map[sprint.number] = tl_id

        # Store both IDs in a single SPRINT-N entry (matches migration script schema)
        id_map = self._load_id_map()
        id_map[f"SPRINT-{sprint.number}"] = {
            "teamwork_id": ms_id,
            "teamwork_url": sprint.tracker_url,
            "tasklist_id": tl_id,
            "title": tl_name,
        }
        self._id_map_path.parent.mkdir(parents=True, exist_ok=True)
        self._id_map_path.write_text(json.dumps(id_map, indent=2), encoding="utf-8")

        return sprint

    def get_sprint_backlog(self, sprint_num: int) -> list[Story]:
        ms_id = self._get_milestone_id(sprint_num)
        if ms_id is None:
            return []
        story_tag_id = self._get_tag_id(self._entity_tag("story"))
        tag_ids = [story_tag_id]
        spec_tags = self._spec_tag_filter_ids()
        if spec_tags:
            tag_ids = list(set(tag_ids + spec_tags))
        list_kwargs: dict = {"milestone_id": ms_id, "tag_ids": tag_ids}
        tl = self._spec_tasklist_id()
        if tl:
            list_kwargs["tasklist_id"] = tl
        tasks = self.transport.list_tasks(**list_kwargs)
        return [self._task_to_story(t) for t in tasks]

    def assign_to_sprint(self, story_id: str, sprint_num: int) -> Story:
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            raise AdapterError(f"Story not found: {story_id}")
        ms_id = self._get_milestone_id(sprint_num)
        if ms_id is None:
            raise AdapterError(f"Sprint milestone not found: {sprint_num}")
        self.transport.update_task(tw_id, milestoneId=ms_id)
        # Story stays in BACKLOG — transitions to TO_DO when sprint starts
        return self.get_story(story_id) or Story(id=story_id, title="")

    def remove_from_sprint(self, story_id: str, sprint_num: int) -> Story:
        tw_id = self._resolve_id(story_id)
        if tw_id is None:
            raise AdapterError(f"Story not found: {story_id}")
        # Clear milestone by setting to 0
        self.transport.update_task(tw_id, milestoneId=0)
        return self.get_story(story_id) or Story(id=story_id, title="")

    def close_sprint(self, sprint_num: int) -> SprintInfo:
        ms_id = self._get_milestone_id(sprint_num)
        if ms_id is None:
            raise AdapterError(f"Sprint milestone not found: {sprint_num}")
        self.transport.complete_milestone(ms_id)
        return self.get_sprint(sprint_num) or SprintInfo(number=sprint_num, goal="")

    def move_incomplete_to_next(self, from_sprint: int, to_sprint: int) -> list[Story]:
        stories = self.get_sprint_backlog(from_sprint)
        # CANCELLED is terminal (PO cancel, #116) — never carried forward.
        incomplete = [s for s in stories
                      if s.status not in ("DONE", "COMPLETED", "CANCELLED")]
        for s in incomplete:
            self.assign_to_sprint(s.id, to_sprint)
        return incomplete

    def get_sprint_metrics(self, sprint_num: int) -> SprintMetrics:
        stories = self.get_sprint_backlog(sprint_num)
        planned = len(stories)
        completed = sum(1 for s in stories if s.status in ("DONE", "COMPLETED"))
        in_progress = sum(1 for s in stories if s.status in ("IN_PROGRESS", "IN_REVIEW"))
        blocked = sum(1 for s in stories if s.status == "BLOCKED")
        return SprintMetrics(
            planned=planned, completed=completed,
            in_progress=in_progress, blocked=blocked,
            velocity=float(completed),
        )

    # ── Backlog Operations ───────────────────────────────────

    def get_backlog(self) -> list[BacklogItem]:
        story_tag_id = self._get_tag_id(self._entity_tag("story"))
        tag_ids = [story_tag_id]
        spec_tags = self._spec_tag_filter_ids()
        if spec_tags:
            tag_ids = list(set(tag_ids + spec_tags))
        list_kwargs: dict = {"tag_ids": tag_ids}
        tl = self._spec_tasklist_id()
        if tl:
            list_kwargs["tasklist_id"] = tl
        tasks = self.transport.list_tasks(**list_kwargs)
        items = [self._task_to_backlog_item(t) for t in tasks]
        order = self._load_backlog_order()
        if order:
            order_map = {sid: pos for pos, sid in enumerate(order)}
            items.sort(key=lambda i: order_map.get(i.id, 9999))
        return items

    def query_tickets(self, query_filter: QueryFilter) -> list[BacklogItem]:
        items = self.get_backlog()
        if query_filter.status:
            items = [i for i in items if i.status in query_filter.status]
        if query_filter.priority:
            items = [i for i in items if i.priority in query_filter.priority]
        if query_filter.sprint is not None:
            items = [i for i in items if i.sprint == str(query_filter.sprint)]
        if query_filter.text:
            q = query_filter.text.lower()
            items = [i for i in items if q in i.title.lower() or q in i.id.lower()]
        if query_filter.assignee:
            target = query_filter.assignee
            # #187 — `currentUser()` is a Jira-only JQL sentinel. On Teamwork it
            # must be resolved to the caller's numeric person id, else it
            # matches no assignee and `--mine` silently returns nothing.
            if target == "currentUser()":
                target = self.transport.current_user()
            items = [i for i in items if i.assignee == target]
        return items

    # ── Reporting Operations ─────────────────────────────────

    def get_velocity_data(self, num_sprints: int = 0) -> list[dict]:
        sprints = self.list_sprints()
        data = []
        for s in sprints:
            metrics = self.get_sprint_metrics(s.number)
            data.append({
                "sprint": s.number,
                "planned": metrics.planned,
                "completed": metrics.completed,
            })
        if num_sprints > 0:
            data = data[-num_sprints:]
        return data

    def get_sprint_report_data(self, sprint_num: int) -> dict:
        metrics = self.get_sprint_metrics(sprint_num)
        sprint = self.get_sprint(sprint_num)
        stories = self.get_sprint_backlog(sprint_num)
        return {
            "sprint_num": sprint_num,
            "sprint_goal": sprint.goal if sprint else f"Sprint {sprint_num}",
            "stories": {
                "planned": metrics.planned,
                "completed": metrics.completed,
                "in_progress": metrics.in_progress,
                "blocked": metrics.blocked,
                "completion_pct": round(
                    (metrics.completed / metrics.planned * 100) if metrics.planned > 0 else 0
                ),
                "status_by_story": [
                    {"id": s.id, "title": s.title, "status": s.status,
                     "priority": s.priority, "size": s.size, "feature": s.feature}
                    for s in stories
                ],
            },
        }

    def get_burndown_data(self, sprint_num: int) -> list[dict]:
        # Teamwork does not expose burndown data via API
        return []

    # ── Private Helpers ──────────────────────────────────────

    def _task_to_epic(self, task: dict) -> Epic:
        synaptory_id = self._extract_synaptory_id(task)
        return Epic(
            id=synaptory_id or f"TW-{task.get('id', '')}",
            title=task.get("name", ""),
            tracker_id=str(task.get("id", "")),
            tracker_url=self._build_task_url(task.get("id", 0)),
        )

    def _task_to_story(self, task: dict) -> Story:
        synaptory_id = self._extract_synaptory_id(task)
        tags = self._get_task_tag_names(task)

        # Status from completed state + status tags. Tag names resolve through
        # the status_map override so custom tag names read back to their
        # canonical states. All four tag-backed states round-trip: completed
        # splits into CANCELLED (PO cancel, #116) vs DONE; open discriminates
        # BLOCKED / IN_REVIEW / AWAITING_ACCEPTANCE.
        if task.get("completed") or task.get("status") == "completed":
            if self._status_tag("CANCELLED") in tags:
                status = "CANCELLED"
            else:
                status = "DONE"
        elif self._status_tag("BLOCKED") in tags:
            status = "BLOCKED"
        elif self._status_tag("IN_REVIEW") in tags:
            status = "IN_REVIEW"
        elif self._status_tag("AWAITING_ACCEPTANCE") in tags:
            status = "AWAITING_ACCEPTANCE"
        else:
            status = "TO_DO"

        # Priority from native field
        tw_priority = task.get("priority", "")
        priority = PRIORITY_REVERSE.get(tw_priority, "")

        # Size from points tag
        size = ""
        for tag_name in tags:
            if tag_name.startswith("points:"):
                pts_str = tag_name[7:]
                try:
                    size = POINTS_TO_SIZE.get(int(pts_str), pts_str)
                except ValueError:
                    pass

        # Sprint from milestone
        sprint = ""
        milestone = task.get("milestone")
        if isinstance(milestone, dict):
            ms_name = milestone.get("name", "")
            if ms_name.startswith(self.milestone_prefix):
                sprint = ms_name[len(self.milestone_prefix):]
        elif task.get("milestoneId"):
            # Try to resolve milestone name from ID
            ms_id = task["milestoneId"]
            for s in self.list_sprints():
                if s.tracker_id == str(ms_id):
                    sprint = str(s.number)
                    break

        # Feature from description ref line
        feature = ""
        description = task.get("description", "")
        feat_m = re.search(r'Feature:\s*`?(\S+?)`?(?:\s|$)', description)
        if feat_m:
            feature = feat_m.group(1)

        # Epic from tag (post-fix: epics are tags, not parent tasks).
        # Fall back to parentTaskId reverse-lookup for tasks created before the fix.
        epic = ""
        id_map = self._load_id_map()
        for tag_name in tags:
            if id_map.get(tag_name, {}).get("type") == "epic":
                epic = tag_name
                break
        if not epic:
            parent_id = task.get("parentTaskId") or task.get("parentId")
            if parent_id:
                for hid, mapping in id_map.items():
                    if mapping.get("teamwork_id") == parent_id:
                        epic = hid
                        break

        acs = self._parse_checklist_acs(description)

        # Assignee
        responsible = task.get("responsiblePartyIds") or []
        assignee_value = None
        if responsible:
            assignee_value = str(responsible[0])

        return Story(
            id=synaptory_id or f"TW-{task.get('id', '')}",
            title=task.get("name", ""),
            feature=feature,
            epic=epic,
            status=status,
            priority=priority,
            size=size,
            sprint=sprint,
            ac_count=len(acs),
            acceptance_criteria=acs,
            assignee=assignee_value,
            tracker_id=str(task.get("id", "")),
            tracker_url=self._build_task_url(task.get("id", 0)),
        )

    def _task_to_backlog_item(self, task: dict) -> BacklogItem:
        story = self._task_to_story(task)
        return BacklogItem(
            id=story.id, title=story.title, feature=story.feature,
            priority=story.priority, status=story.status,
            size=story.size, sprint=story.sprint, assignee=story.assignee,
        )

    def _extract_synaptory_id(self, task: dict) -> str:
        """Extract synaptory ID from task tags or description metadata."""
        tags = self._get_task_tag_names(task)
        for tag_name in tags:
            if re.match(r'^(US|EPIC|FEAT|BUG|ENH|TASK|S\d+)-\w+$', tag_name):
                return tag_name

        # Fallback: description metadata
        description = task.get("description", "")
        m = re.search(r'synaptory:\s*`?(\S+?)`?(?:\s|$)', description)
        if m:
            return m.group(1)

        return ""

    def _extract_synaptory_ids(self, tasks: list[dict]) -> list[str]:
        return [hid for t in tasks if (hid := self._extract_synaptory_id(t))]

    @staticmethod
    def _get_task_tag_names(task: dict) -> list[str]:
        """Extract tag names from a task dict.

        Teamwork v3 returns `tags: null` (not `[]`) for never-tagged tasks,
        so `.get("tags", [])` is not null-safe — coerce explicitly (#108).
        """
        tags = task.get("tags") or []
        names = []
        for tag in tags:
            if isinstance(tag, dict):
                names.append(tag.get("name", ""))
            elif isinstance(tag, str):
                names.append(tag)
        return names

    @staticmethod
    def _parse_checklist_acs(description: str) -> list[AcceptanceCriterion]:
        """Parse acceptance criteria from task description checklist.

        Supports multiple formats (all bullet styles):
        - ``* [x] **AC-01: Title**``  (preferred — Teamwork checkbox, no strikethrough)
        - ``- [x] **AC-01: Title**``  (legacy dash variant)
        - ``* ✅ **AC-01: Title**``   (emoji variant)
        - ``- ✅ **AC-01: Title**``   (emoji dash variant)

        Also parses Given/When/Then sub-bullets following each AC.

        Both checkbox and emoji formats match the title non-greedily, so
        they stop at the first ``**`` they find. A title with its own
        internal bold (e.g. emphasising a negation) has a second ``**``
        pair later on the line that the non-greedy match never reaches —
        silently truncating the title instead of raising. Reject and
        report that case rather than guess (#778).

        Only the character right after the matched ``**`` decides this.
        Trailing content after a clean close — e.g. the ``**Title** —
        {{AC_SUMMARY}}`` shape templates use — starts with whitespace and
        is legitimate even when that summary itself contains unrelated
        bold; a ``**`` butted straight up against more text is the
        signature of a nested-bold title that was cut mid-word.
        """
        acs = []
        if not description:
            return acs
        for line in description.splitlines():
            stripped = line.strip()
            # Given/When/Then lines attach to the most recent AC
            gwt_match = re.match(r"[*\-] (Given|When|Then)\s+(.*)", stripped)
            if gwt_match and acs:
                keyword = gwt_match.group(1).lower()
                value = gwt_match.group(2).strip()
                if keyword == "given":
                    acs[-1].given = value
                elif keyword == "when":
                    acs[-1].when = value
                elif keyword == "then":
                    acs[-1].then = value
                continue
            # Checkbox format: * [x] or - [x] or * [ ] or - [ ]
            m = re.match(r"[*\-] \[([xX ])\] \*\*(AC-\w+):\s*(.*?)\*\*", stripped)
            if m:
                tail = stripped[m.end():]
                if tail and not tail[0].isspace():
                    _warn(
                        f"acceptance criterion {m.group(2)} was not parsed: its title "
                        "contains markdown bold ('**') that makes the closing delimiter "
                        f"ambiguous — rewrite the title without nested bold. Line: {stripped!r}"
                    )
                    continue
                acs.append(AcceptanceCriterion(
                    id=m.group(2), text=m.group(3).strip(), met=m.group(1).lower() == "x",
                ))
                continue
            # Emoji format: * ✅ or - ✅ or * ⬜ or - ⬜
            m = re.match(r"[*\-] ([✅⬜]) \*\*(AC-\w+):\s*(.*?)\*\*", stripped)
            if m:
                tail = stripped[m.end():]
                if tail and not tail[0].isspace():
                    _warn(
                        f"acceptance criterion {m.group(2)} was not parsed: its title "
                        "contains markdown bold ('**') that makes the closing delimiter "
                        f"ambiguous — rewrite the title without nested bold. Line: {stripped!r}"
                    )
                    continue
                acs.append(AcceptanceCriterion(
                    id=m.group(2), text=m.group(3).strip(), met=m.group(1) == "✅",
                ))
        return acs

    def _get_tag_id(self, name: str) -> int:
        """Get a tag ID by name, using cache or creating on demand."""
        if name in self._tag_cache:
            return self._tag_cache[name]
        tag_id = self.transport.get_or_create_tag(name)
        self._tag_cache[name] = tag_id
        return tag_id

    def _add_tag_to_task(self, task_id: int, tag_id: int) -> None:
        """Add a tag to a task by updating its tag list."""
        task = self.transport.get_task(task_id)
        existing_tags = task.get("tags") or []  # tags can be null on fresh tasks (#108)
        existing_ids = [t.get("id", 0) if isinstance(t, dict) else 0 for t in existing_tags]
        if tag_id not in existing_ids:
            existing_ids.append(tag_id)
            self.transport.update_task(task_id, tagIds=existing_ids)

    def _remove_tag_from_task(self, task_id: int, tag_id: int) -> None:
        """Remove a tag from a task by updating its tag list."""
        task = self.transport.get_task(task_id)
        existing_tags = task.get("tags") or []  # tags can be null on fresh tasks (#108)
        existing_ids = [t.get("id", 0) if isinstance(t, dict) else 0 for t in existing_tags]
        if tag_id in existing_ids:
            existing_ids.remove(tag_id)
            self.transport.update_task(task_id, tagIds=existing_ids)

    def _update_points_tag(self, task_id: int, new_size: str) -> None:
        """Swap the points tag on a task."""
        task = self.transport.get_task(task_id)
        existing_tags = task.get("tags") or []  # tags can be null on fresh tasks (#108)
        existing_ids = [t.get("id", 0) if isinstance(t, dict) else 0 for t in existing_tags]

        # Remove old points tags
        for pts in [1, 2, 3, 5, 8, 13]:
            old_tag_id = self._tag_cache.get(f"points:{pts}")
            if old_tag_id and old_tag_id in existing_ids:
                existing_ids.remove(old_tag_id)

        # Add new points tag
        if new_size in SIZE_TO_POINTS:
            new_tag_id = self._get_tag_id(f"points:{SIZE_TO_POINTS[new_size]}")
            existing_ids.append(new_tag_id)

        self.transport.update_task(task_id, tagIds=existing_ids)

    def _get_milestone_id(self, sprint_num: int) -> Optional[int]:
        """Resolve a sprint number to a Teamwork milestone ID."""
        # Check ID map first — supports both adapter format (teamwork_id) and
        # migration script format (milestone_id) in the same SPRINT-N entry
        entry = self._load_id_map().get(f"SPRINT-{sprint_num}")
        if entry:
            tw_id = entry.get("teamwork_id") or entry.get("milestone_id")
            if tw_id:
                return tw_id

        # Fallback: search milestones
        for ms in self.transport.list_milestones():
            name = ms.get("name", "")
            if name == f"{self.milestone_prefix}{sprint_num}":
                return ms.get("id")
        return None

    def _get_sprint_tasklist_id(self, sprint_num: int) -> Optional[int]:
        """Resolve a sprint number to its Teamwork tasklist ID."""
        if sprint_num in self._sprint_tasklist_map:
            return self._sprint_tasklist_map[sprint_num]
        # Rehydrate from id-map on cold start — tasklist_id lives in the SPRINT-N entry
        entry = self._load_id_map().get(f"SPRINT-{sprint_num}")
        if entry:
            tl_id = entry.get("tasklist_id")
            if tl_id:
                self._sprint_tasklist_map[sprint_num] = tl_id
                return tl_id
        return None

    def _get_or_create_backlog_tasklist(self) -> int:
        """Get or create the fallback 'synaptory Backlog' tasklist for unsprinted tasks."""
        if self._backlog_tasklist_id is None:
            self._backlog_tasklist_id = self.transport.get_or_create_tasklist("synaptory Backlog")
        return self._backlog_tasklist_id

    def _build_task_url(self, task_id: int) -> str:
        return f"https://{self.transport.site_name}.teamwork.com/app/tasks/{task_id}"

    def _build_milestone_url(self, milestone_id: int) -> str:
        return f"https://{self.transport.site_name}.teamwork.com/app/milestones/{milestone_id}"

    def _load_id_map(self) -> dict:
        if self._id_map is not None:
            return self._id_map
        if self._id_map_path.exists():
            try:
                self._id_map = json.loads(self._id_map_path.read_text(encoding="utf-8"))
            except Exception:
                self._id_map = {}
        else:
            self._id_map = {}
        return self._id_map

    def _save_id_mapping(self, synaptory_id: str, tw_id: int, url: str = "", **extra) -> None:
        id_map = self._load_id_map()
        entry = {"teamwork_id": tw_id, "teamwork_url": url}
        entry.update(extra)
        id_map[synaptory_id] = entry
        self._id_map_path.parent.mkdir(parents=True, exist_ok=True)
        self._id_map_path.write_text(json.dumps(id_map, indent=2), encoding="utf-8")

    def _resolve_id(self, synaptory_id: str) -> Optional[int]:
        """Resolve a synaptory ID to a Teamwork task ID."""
        id_map = self._load_id_map()
        entry = id_map.get(synaptory_id)
        if entry:
            return entry.get("teamwork_id") or entry.get("task_id")
        return None

    def _load_backlog_order(self) -> list[str]:
        if self._backlog_order_path.exists():
            try:
                return json.loads(self._backlog_order_path.read_text(encoding="utf-8"))
            except Exception:
                return []
        return []

    def _save_backlog_order(self, order: list[str]) -> None:
        self._backlog_order_path.parent.mkdir(parents=True, exist_ok=True)
        self._backlog_order_path.write_text(json.dumps(order, indent=2), encoding="utf-8")
